  `level` int NOT NULL COMMENT '层级距离 (1表示直属上级, 2表示上上级...)',
  `rate` float NULL DEFAULT NULL COMMENT '返点比例 (如 0.0050 表示 0.5%)',
  PRIMARY KEY (`level`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销返点比例配置' ROW_FORMAT = Dynamic;

