-- Table structure for games
-- ----------------------------
DROP TABLE IF EXISTS `games`;
CREATE TABLE `games`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `provider_id` smallint NULL DEFAULT NULL COMMENT '关联厂商ID (game_providers.id)',
  `game_type_id` smallint NULL DEFAULT NULL COMMENT '关联分类ID (game_types.id)',
  `game_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商侧的游戏ID',
