  INDEX `idx_sort_views`(`sort` ASC, `views` ASC) USING BTREE,
  UNIQUE INDEX `idx_provider_game_code`(`provider_id` ASC, `game_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5771 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '游戏库' ROW_FORMAT = Dynamic;

