  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '正文',
  `attachments` json NULL COMMENT '附件奖励 [{\"type\":\"balance\",\"value\":100}]',
  `admin_id` bigint NULL DEFAULT 0,
